import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`smb-reviews`,heroTitle:`Understand your customer reviews in minutes`,heroSubtitle:`Perplexity Computer collects your reviews, analyzes sentiment, and surfaces bugs and feedback — automatically.`,heroCta:`Analyze my reviews`,inputUrlCta:`Analyze my reviews`,inputUrlPlaceholder:`e.g. your Google Business, Yelp, or product page URL`,inputUrlPrefill:`Go to {url} and find all customer reviews, ratings, and feedback across the site. Analyze every review for: 1) Overall sentiment breakdown (positive, neutral, negative with percentages), 2) Top 10 recurring complaints and bug reports ranked by frequency, 3) Top 10 feature requests and positive themes, 4) A prioritized action plan for the 5 most urgent issues to fix, 5) A summary report with trends over time if dates are available. Present everything in a structured report I can share with my team.`,heroOverlaySteps:[`Collecting every customer review and rating from your page`,`Classifying sentiment across hundreds of reviews`,`Extracting bug reports, complaints, and feature requests`,`Prioritized action plan and sentiment dashboard — ready to share`],generatingSteps:[`Visiting {url} to collect customer reviews, ratings, and feedback`,`Designing an agent to classify sentiment and extract recurring themes across every review`,`Configuring bug detection, complaint clustering, and feature request extraction`,`Setting up a prioritized action plan and summary report for your team`],featureSectionTitle:`From raw reviews to clear action items`,featureCardTitles:[`Connects to your support stack`,`Outputs you can act on`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Zendesk, Intercom, Google Sheets, Slack, Notion — Computer plugs into your tools so review insights flow straight into your support and product workflows.`,`Sentiment breakdowns. Bug report summaries. Feature request rankings. Prioritized fix lists. Computer delivers structured reports your team can execute on immediately.`],capabilitySectionTitle:`Your support analyst, on autopilot`,capabilitySectionSubtitle:`Paste your review page, step away, come back to a complete sentiment report.`,capabilityCards:[{title:`Sentiment Analysis`,description:`Computer can read every review and classify sentiment — positive, negative, neutral — with percentage breakdowns and trend tracking over time.`},{title:`Bug Detection`,description:`Computer can surface recurring bugs, errors, and product issues from customer language — ranked by frequency so you fix what matters most.`},{title:`Feedback Clustering`,description:`Computer can group feature requests, complaints, and praise into themes — giving you a clear picture of what customers want next.`},{title:`Connect Your Tools`,description:`Computer can read and write to Zendesk, Intercom, Google Sheets, Slack, and Notion — build workflows that route insights to the right team.`},{title:`Remember & Learn`,description:`Computer can remember your product context, known issues, and past review cycles — so every analysis builds on what came before.`},{title:`Monitor & Alert`,description:`Computer can watch for new negative reviews and spike patterns — set up a monitoring workflow that pings you when sentiment drops.`}]});export{t as default};
